    private final ContactMessageService messageService;

    private final TextField name = new TextField("Name");
    private final EmailField email = new EmailField("Email");
    private final TextField phone = new TextField("Phone");
    private final TextArea message = new TextArea("Message");
    private final Button send = new Button("Send");
    private final Grid<ContactMessage> sentMessages = new Grid<>();
    private final Dialog leaveDialog = new Dialog();

    private ContinueNavigationAction pendingLeave;
    // Once a send has failed, every edit re-checks the form so the marks follow what the user fixes.
    private boolean sendFailed;

    public ContactView(ContactMessageService messageService) {
        this.messageService = messageService;

        // Keeps the server's value current on every keystroke, so Enter sends what is on screen.
        name.setValueChangeMode(ValueChangeMode.EAGER);
        email.setValueChangeMode(ValueChangeMode.EAGER);
        phone.setValueChangeMode(ValueChangeMode.EAGER);
        message.setValueChangeMode(ValueChangeMode.EAGER);

        // Validation happens only when Send is pressed, not in the browser's own e-mail check.
        email.setManualValidation(true);

        name.addValueChangeListener(event -> onEdit());
        email.addValueChangeListener(event -> onEdit());
        phone.addValueChangeListener(event -> onEdit());
        message.addValueChangeListener(event -> onEdit());

        send.addClickListener(click -> sendMessage());

        FormLayout form = new FormLayout(name, email, phone, message);
        form.setResponsiveSteps(new ResponsiveStep("0", 1), new ResponsiveStep("40em", 2));
        form.setColspan(message, 2);

        // Enter in any of the form's inputs presses Send. Enter inside the TextArea sends too, not a new line.
        Shortcuts.addShortcutListener(form, () -> send.click(), Key.ENTER)

