+import java.util.concurrent.ConcurrentLinkedDeque;
+
+/**
+ * Keeps every message sent during this run of the application, in memory.
+ */
+@Service
+public class ContactMessageService {
+
+    private final Deque<ContactMessage> sent = new ConcurrentLinkedDeque<>();
+
+    public void add(ContactMessage message) {
