+            "[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?"
+                    + "(?:\\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+");
+
+    private final ContactMessageService messageService;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> sentMessages = new Grid<>();
+
+    // Once a send has failed, every edit re-checks the form so the marks follow what the user fixes.
+    private boolean sendFailed;
+
+    public ContactView(ContactMessageService messageService) {
+        this.messageService = messageService;
+
+        // Keeps the server's value current on every keystroke, so Enter sends what is on screen.
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+
+        // Validation happens only when Send is pressed, not in the browser's own e-mail check.
+        email.setManualValidation(true);
+
+        name.addValueChangeListener(event -> onEdit());
+        email.addValueChangeListener(event -> onEdit());
+        phone.addValueChangeListener(event -> onEdit());
+        message.addValueChangeListener(event -> onEdit());
+
+        send.addClickListener(click -> sendMessage());
+
+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setResponsiveSteps(new ResponsiveStep("0", 1), new ResponsiveStep("40em", 2));
+        form.setColspan(message, 2);
+
+        // Enter presses Send while this view is open, whichever element has focus. The shortcut is on the UI,
+        // and it suppresses the browser's default, so Enter in the TextArea does not add a new line.
+        whenAttached(ui -> Shortcuts.addShortcutListener(ui, () -> send.click(), Key.ENTER));
+
+        sentMessages.addColumn(ContactMessage::name).setHeader("Name");
+        sentMessages.addColumn(ContactMessage::email).setHeader("Email");
+        sentMessages.addColumn(ContactMessage::phone).setHeader("Phone");
+        sentMessages.addColumn(ContactMessage::message).setHeader("Message");
+        sentMessages.setAllRowsVisible(true);
+        showSentMessages();
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, send, sentMessages);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsentInput()) {
+            askBeforeLeaving(event.postpone());
+        }
+    }
+
+    // Only Discard lets the postponed navigation go ahead. Keep editing, Esc and a click outside all leave it postponed.
+    private void askBeforeLeaving(ContinueNavigationAction leave) {
+        Dialog dialog = new Dialog("Leave without sending?");
+        dialog.add(new Paragraph("The form has text in it that has not been sent. Leaving now discards it."));
+        Button keepEditing = new Button("Keep editing", click -> dialog.close());
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            leave.proceed();
+        });
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.addClosedListener(closed -> dialog.removeFromParent());
+        add(dialog);
+        dialog.open();
+    }
+
+    private boolean hasUnsentInput() {
+        return !name.getValue().isEmpty() || !email.getValue().isEmpty()
+                || !phone.getValue().isEmpty() || !message.getValue().isEmpty();
+    }
+
+    private void onEdit() {
+        send.setEnabled(true);
+        if (sendFailed) {
+            validate();
+        }
+    }
+
+    private void sendMessage() {
+        if (!validate()) {
+            sendFailed = true;
+            return;
+        }
+        messageService.add(new ContactMessage(
+                name.getValue().trim(),
+                email.getValue().trim(),
+                phone.getValue().trim(),
+                message.getValue().trim()));
+        sendFailed = false;
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        // Clearing the fields re-enables Send through onEdit(), so disable it last.
+        send.setEnabled(false);
+        showSentMessages();
+        Notification.show("Message sent");
+    }
+
+    private boolean validate() {
+        String nameValue = name.getValue().trim();
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        String messageValue = message.getValue().trim();
+
+        String nameError = nameValue.isEmpty() ? "Name is required" : null;
+
+        String emailError = null;
+        if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            emailError = "Give an e-mail address or a phone number";
+        } else if (!emailValue.isEmpty() && !EMAIL_ADDRESS.matcher(emailValue).matches()) {
+            emailError = "Enter a valid e-mail address";
+        }
+
+        String messageError = null;
+        if (messageValue.isEmpty()) {
+            messageError = "Message is required";
+        } else if (messageValue.codePointCount(0, messageValue.length()) > MAX_MESSAGE_LENGTH) {
+            messageError = "Message must be at most " + MAX_MESSAGE_LENGTH + " characters";
+        }
+
+        setError(name, nameError);
+        setError(email, emailError);
+        setError(message, messageError);
+        return nameError == null && emailError == null && messageError == null;
+    }
+
+    private static void setError(HasValidation field, String error) {
+        field.setInvalid(error != null);
+        field.setErrorMessage(error == null ? "" : error);
+    }
+
+    private void showSentMessages() {
+        sentMessages.setItems(messageService.findNewestFirst());
+    }
+}
