+package com.example.contact;
+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.AfterAll;
+import org.junit.jupiter.api.AfterEach;
+import org.junit.jupiter.api.BeforeAll;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.GridElement;
+
+import java.util.UUID;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/contact";
+    }
+
+    @BeforeAll
+    static void startBrowser() {
+        setup();
+    }
+
+    @AfterAll
+    static void stopBrowser() {
+        cleanup();
+    }
+
+    @BeforeEach
+    void openContactPage() throws Exception {
+        setupTest();
+    }
+
+    @AfterEach
+    void closeContactPage() {
+        cleanupTest();
+    }
+
+    @Test
+    void sendingWithTheButtonListsTheMessageFirstAndResetsTheForm() {
+        String sender = sender("button");
+        fill("Name", sender);
+        fill("Phone", "555-0200");
+        fill("Message", "Hello from the browser");
+
+        sendButton().click();
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(firstGridCell()).hasText(sender);
+        assertThat(page.getByLabel("Name", exact())).hasValue("");
+        assertThat(page.getByLabel("Message", exact())).hasValue("");
+        assertThat(sendButton()).isDisabled();
+
+        page.getByLabel("Name", exact()).fill("Typing again");
+
+        assertThat(sendButton()).isEnabled();
+    }
+
+    @Test
+    void enterInAFieldSendsTheMessageExactlyOnce() {
+        String sender = sender("enter");
+        fill("Name", sender);
+        fill("Phone", "555-0201");
+        fill("Message", "Sent with Enter");
+
+        page.getByLabel("Phone", exact()).press("Enter");
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(firstGridCell()).hasText(sender);
+        assertThat(page.getByText(sender, exactText())).hasCount(1);
+        assertThat(page.getByText("Name is required")).hasCount(0);
+    }
+
+    @Test
+    void enterInTheMessageAreaSendsWithoutAddingALine() {
+        String sender = sender("textarea");
+        fill("Name", sender);
+        fill("Phone", "555-0202");
+        fill("Message", "Enter ends the message");
+
+        page.getByLabel("Message", exact()).press("Enter");
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(firstGridCell()).hasText(sender);
+        assertThat(page.getByLabel("Message", exact())).hasValue("");
+    }
+
+    @Test
+    void enterOnAFocusedSendButtonSendsExactlyOnce() {
+        String sender = sender("focused");
+        fill("Name", sender);
+        fill("Phone", "555-0203");
+        fill("Message", "Focus then Enter");
+
+        sendButton().focus();
+        page.keyboard().press("Enter");
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(page.getByText(sender, exactText())).hasCount(1);
+        assertThat(page.getByText("Message is required")).hasCount(0);
+    }
+
+    @Test
+    void emptySendMarksTheRequiredFields() {
+        sendButton().click();
+
+        assertThat(page.getByText("Name is required")).isVisible();
+        assertThat(page.getByText("Give an e-mail address or a phone number")).isVisible();
+        assertThat(page.getByText("Message is required")).isVisible();
+        assertThat(page.getByText("Message sent")).hasCount(0);
+    }
+
+    @Test
+    void emailIsOnlyCheckedWhenSendIsPressed() {
+        fill("Name", sender("email-check"));
+        fill("Email", "not-an-address");
+
+        assertThat(page.getByText("Enter a valid e-mail address")).hasCount(0);
+
+        fill("Message", "Hi");
+        sendButton().click();
+
+        assertThat(page.getByText("Enter a valid e-mail address")).isVisible();
+    }
+
+    @Test
+    void aboutLinkNavigatesWithoutReloadingThePage() {
+        page.evaluate("window.__noReload = 42");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About").setExact(true)).click();
+
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About").setExact(true)))
+                .isVisible();
+        assertTrue(page.url().endsWith("/about"), page.url());
+        assertEquals(42, ((Number) page.evaluate("window.__noReload")).intValue());
+    }
+
+    @Test
+    void leavingWithTypedInputAsksFirstAndKeepEditingStaysPut() {
+        fill("Name", "Half-written");
+
+        aboutLink().click();
+
+        assertThat(keepEditingButton()).isVisible();
+        assertThat(discardButton()).isVisible();
+        assertTrue(page.url().endsWith("/contact"), page.url());
+
+        keepEditingButton().click();
+
+        assertThat(keepEditingButton()).isHidden();
+        assertTrue(page.url().endsWith("/contact"), page.url());
+        assertThat(page.getByLabel("Name", exact())).hasValue("Half-written");
+    }
+
+    @Test
+    void discardLeavesForTheAboutView() {
+        fill("Name", "Thrown away");
+
+        aboutLink().click();
+        discardButton().click();
+
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About").setExact(true)))
+                .isVisible();
+        assertTrue(page.url().endsWith("/about"), page.url());
+    }
+
+    @Test
+    void escapeClosesTheDialogAndKeepsTheUserOnTheForm() {
+        fill("Name", "Still here");
+
+        aboutLink().click();
+        assertThat(keepEditingButton()).isVisible();
+        page.keyboard().press("Escape");
+
+        assertThat(keepEditingButton()).isHidden();
+        assertTrue(page.url().endsWith("/contact"), page.url());
+        assertThat(page.getByLabel("Name", exact())).hasValue("Still here");
+    }
+
+    @Test
+    void leavingWithAnEmptyFormDoesNotAsk() {
+        aboutLink().click();
+
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About").setExact(true)))
+                .isVisible();
+        assertThat(keepEditingButton()).hasCount(0);
+    }
+
+    @Test
+    void enterInsideTheLeaveDialogDoesNotSendTheForm() {
+        String sender = sender("dialog-enter");
+        fill("Name", sender);
+        fill("Phone", "555-0204");
+        fill("Message", "Must not be sent from the dialog");
+
+        aboutLink().click();
+        assertThat(keepEditingButton()).isVisible();
+        keepEditingButton().focus();
+        page.keyboard().press("Enter");
+
+        assertThat(keepEditingButton()).isHidden();
+        assertThat(page.getByText("Message sent")).hasCount(0);
+        assertThat(page.getByText(sender, exactText())).hasCount(0);
+    }
+
+    @Test
+    void browserForwardAlsoAsksBeforeLeaving() {
+        // The router creates the history entries, so going back and forward between them is a client-side navigation.
+        aboutLink().click();
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About").setExact(true)))
+                .isVisible();
+        page.goBack();
+        assertThat(page.getByLabel("Name", exact())).isVisible();
+        fill("Name", "Back button");
+
+        page.goForward();
+
+        assertThat(keepEditingButton()).isVisible();
+        keepEditingButton().click();
+
+        assertThat(keepEditingButton()).isHidden();
+        assertThat(page.getByLabel("Name", exact())).hasValue("Back button");
+        assertTrue(page.url().endsWith("/contact"), page.url());
+    }
+
+    @Test
+    void sentMessagesAreStillListedAfterReturningToTheView() {
+        String sender = sender("returning");
+        fill("Name", sender);
+        fill("Phone", "555-0205");
+        fill("Message", "Still there later");
+        sendButton().click();
+        assertThat(page.getByText("Message sent")).isVisible();
+
+        page.navigate(getUrl());
+
+        assertThat(page.getByText(sender, exactText())).hasCount(1);
+        assertThat(firstGridCell()).hasText(sender);
+    }
+
+    private static String sender(String tag) {
+        return tag + "-" + UUID.randomUUID();
+    }
+
+    private static Page.GetByLabelOptions exact() {
+        return new Page.GetByLabelOptions().setExact(true);
+    }
+
+    private static Page.GetByTextOptions exactText() {
+        return new Page.GetByTextOptions().setExact(true);
+    }
+
+    private void fill(String label, String value) {
+        page.getByLabel(label, exact()).fill(value);
+    }
+
+    private Locator sendButton() {
+        return page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send").setExact(true));
+    }
+
+    private Locator aboutLink() {
+        return page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About").setExact(true));
+    }
+
+    private Locator firstGridCell() {
+        return GridElement.get(page).findCell(0, 0).orElseThrow().getCellContentLocator();
+    }
+
+    private Locator keepEditingButton() {
+        return page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing").setExact(true));
+    }
+
+    private Locator discardButton() {
+        return page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard").setExact(true));
+    }
+}
