+package com.example.contact;
+
+import com.example.about.AboutView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.notification.NotificationTester;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import java.util.UUID;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+// The sent list is shared by the whole application context, so every test uses its own sender name.
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void showsHeadingAndAboutLink() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("About", $(RouterLink.class).single().getText());
+    }
+
+    @Test
+    void formStartsEmptyWithSendEnabled() {
+        navigate(ContactView.class);
+
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void emptyFormMarksNameEmailAndMessage() {
+        navigate(ContactView.class);
+
+        send().click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertFalse(phone().isInvalid());
+        assertFalse($(Notification.class).exists());
+    }
+
+    @Test
+    void malformedEmailIsReportedOnEmailField() {
+        navigate(ContactView.class);
+        name().setValue("Mallory");
+        email().setValue("not-an-address");
+        message().setValue("Hello");
+
+        send().click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertFalse(name().isInvalid());
+        assertFalse(message().isInvalid());
+        assertEquals("not-an-address", email().getValue());
+    }
+
+    @Test
+    void phoneNumberAloneIsEnough() {
+        navigate(ContactView.class);
+        String sender = sender("phone");
+        name().setValue(sender);
+        phone().setValue("+358 40 123 4567");
+        message().setValue("Call me");
+
+        send().click();
+
+        assertFalse(email().isInvalid());
+        assertEquals(sender, firstSentMessage().name());
+        assertEquals("+358 40 123 4567", firstSentMessage().phone());
+    }
+
+    @Test
+    void emailAddressAloneIsEnough() {
+        navigate(ContactView.class);
+        String sender = sender("email");
+        name().setValue(sender);
+        email().setValue("someone@example.com");
+        message().setValue("Write to me");
+
+        send().click();
+
+        assertFalse(email().isInvalid());
+        assertEquals(sender, firstSentMessage().name());
+        assertEquals("someone@example.com", firstSentMessage().email());
+    }
+
+    @Test
+    void messageLongerThan500CharactersIsRejectedAndAt500IsAccepted() {
+        navigate(ContactView.class);
+        name().setValue(sender("long"));
+        phone().setValue("12345");
+        message().setValue("x".repeat(501));
+
+        send().click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertEquals("x".repeat(501), message().getValue());
+
+        message().setValue("x".repeat(500));
+        send().click();
+
+        assertFalse(message().isInvalid());
+        assertEquals("x".repeat(500), firstSentMessage().message());
+    }
+
+    @Test
+    void successfulSendNotifiesListsAndClearsTheForm() {
+        navigate(ContactView.class);
+        String sender = sender("send");
+        name().setValue(sender);
+        phone().setValue("555-0100");
+        message().setValue("Hello there");
+
+        send().click();
+
+        NotificationTester<Notification> notification = test($(Notification.class).single());
+        assertEquals("Message sent", notification.getText());
+        assertEquals(sender, firstSentMessage().name());
+        assertEquals("Hello there", firstSentMessage().message());
+        assertEquals("", name().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled());
+    }
+
+    @Test
+    void fixingAMarkedFieldClearsItsErrorAfterAFailedSend() {
+        navigate(ContactView.class);
+        send().click();
+        assertTrue(name().isInvalid());
+
+        name().setValue("Alice");
+
+        assertFalse(name().isInvalid());
+        assertEquals("", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+    }
+
+    @Test
+    void sendIsEnabledAgainAfterAnyEdit() {
+        navigate(ContactView.class);
+        name().setValue(sender("edit"));
+        phone().setValue("555-0101");
+        message().setValue("First");
+        send().click();
+        assertFalse(send().isEnabled());
+
+        name().setValue("Typing again");
+
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterPressesSend() {
+        navigate(ContactView.class);
+        String sender = sender("enter");
+        name().setValue(sender);
+        phone().setValue("555-0102");
+        message().setValue("Sent with Enter");
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(sender, firstSentMessage().name());
+        assertFalse(send().isEnabled());
+    }
+
+    @Test
+    void sentMessagesAreStillListedAfterComingBack() {
+        navigate(ContactView.class);
+        String sender = sender("persist");
+        name().setValue(sender);
+        phone().setValue("555-0103");
+        message().setValue("Remember me");
+        send().click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        assertEquals(sender, firstSentMessage().name());
+    }
+
+    @Test
+    void leavingWithTypedInputAsksFirstAndKeepEditingStays() {
+        navigate(ContactView.class);
+        name().setValue("Half-written");
+
+        test($(RouterLink.class).single()).click();
+
+        assertTrue($(Dialog.class).single().isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        $(Button.class).withText("Keep editing").single().click();
+
+        assertFalse($(Dialog.class).exists());
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Half-written", name().getValue());
+    }
+
+    @Test
+    void discardingLeavesForTheAboutView() {
+        navigate(ContactView.class);
+        name().setValue("Thrown away");
+
+        test($(RouterLink.class).single()).click();
+        $(Button.class).withText("Discard").single().click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void leavingWithEmptyFormDoesNotAskAnything() {
+        navigate(ContactView.class);
+
+        test($(RouterLink.class).single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertFalse($(Dialog.class).exists());
+    }
+
+    private static String sender(String tag) {
+        return tag + "-" + UUID.randomUUID();
+    }
+
+    private ContactMessage firstSentMessage() {
+        @SuppressWarnings("unchecked")
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        return grid.getListDataView().getItems().findFirst().orElseThrow();
+    }
